public class ManifestResourceDetector extends Detector implements XmlScanner {
    private static final String ANDROID_URI = "http://schemas.android.com/apk/res/android";

    @Override
    public Collection<String> getApplicableElements() { return ALL; }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        NamedNodeMap attrs = element.getAttributes();
        for (int i = 0, n = attrs.getLength(); i < n; i++) {
            Attr attr = (Attr) attrs.item(i);
            String value = attr.getValue();
            if (!value.startsWith("@")) continue;
            ResourceUrl url = ResourceUrl.parse(value);
            if (url == null || url.isTheme() || url.framework) continue;
            if (element.getNodeName().equals("application")
                && ANDROID_URI.equals(attr.getNamespaceURI())
                && ("label".equals(attr.getLocalName()) || "icon".equals(attr.getLocalName()))) {
                continue;
            }
            if (hasConfigurationVariation(context, url.type, url.name)) {
                Location location = context.getLocation(attr);
                context.report(ISSUE, attr, location,
                    "Resources referenced from the manifest cannot vary across configurations (except by version); use a resource with the same value in all configurations, or remove the reference.");
            }
        }
    }

    private boolean hasConfigurationVariation(XmlContext context, ResourceType type, String name) {
        List<File> folders = context.getProject().getResourceFolders();
        if (folders == null) return false;
        boolean found = false;
        boolean hasVersionOnly = true;
        for (File folder : folders) {
            if (!folder.isDirectory()) continue;
            File[] typeDirs = folder.listFiles();
            if (typeDirs == null) continue;
            for File typeDir : typeDirs) {
                String dirName = typeDir.getName();
                ResourceFolderType folderType = ResourceFolderType.getFolderType(dirName);
                if (folderType == null || folderType != ResourceFolderType.getTypeByName(type.getName())) continue;
                // parse qualifiers after type name
                String qualifierPart = dirName.substring(type.getName().length());
                if (qualifierPart.startsWith("-")) qualifierPart = qualifierPart.substring(1);
                if (qualifierPart.isEmpty()) continue; // default config, no variation
                // check if all qualifiers are version
                if (!isVersionOnly(qualifierPart)) {
                    // For file based resources, check if resource file exists.
                    if (folderType != ResourceFolderType.VALUES) {
                        File[] files = typeDir.listFiles();
                        if (files != null) {
                            for (File f : files) {
                                if (f.isFile() && f.getName().startsWith(name + ".")) {
                                    return true;
                                }
                            }
                        }
                    }
                }
            }
        }
        // values scanning...
        return false;
    }
}
