private static boolean hasConfigurationVariation(XmlContext context, ResourceType type, String name) {
    List<File> resourceFolders = context.getProject().getResourceFolders();
    if (resourceFolders == null || resourceFolders.isEmpty()) return false;
    for (File resDir : resourceFolders) {
        if (!resDir.isDirectory()) continue;
        File[] typeDirs = resDir.listFiles(File::isDirectory);
        if (typeDirs == null) continue;
        for (File typeDir : typeDirs) {
            String dirName = typeDir.getName();
            ResourceFolderType folderType = ResourceFolderType.getFolderType(dirName);
            if (folderType == null) continue;
            // check if folder can contain this type
            if (!containsResourceType(folderType, type)) continue;
            String qualifiers = dirName.substring(folderType.getName().length());
            if (qualifiers.startsWith("-")) qualifiers = qualifiers.substring(1);
            if (qualifiers.isEmpty() || isVersionOnly(qualifiers)) continue;
            if (folderType == ResourceFolderType.VALUES) {
                if (containsValueResource(typeDir, type, name)) return true;
            } else {
                if (containsFileResource(typeDir, name)) return true;
            }
        }
    }
    return false;
}
```

