private static ResourceRef parseResourceReference(String value) {
    if (!value.startsWith("@")) return null;
    int slash = value.indexOf('/');
    if (slash < 0) return null;
    int typeStart = 1;
    int plus = value.indexOf('+');
    if (plus >= 0 && plus < slash) typeStart = plus + 1;
    String typeAndPackage = value.substring(typeStart, slash);
    // typeAndPackage may be "android:drawable" or "*android:drawable" or "drawable"
    int colon = typeAndPackage.lastIndexOf(':');
    String packageName = colon >= 0 ? typeAndPackage.substring(0, colon) : null;
    String typeName = colon >= 0 ? typeAndPackage.substring(colon + 1) : typeAndPackage;
    String name = value.substring(slash + 1);
    if (typeName.isEmpty() || name.isEmpty() || name.contains(":") etc) return null;
    if (packageName != null && (packageName.equals("android") || packageName.equals("*android") || packageName.startsWith("*"))) return null; // framework
    ResourceType type = ResourceType.getEnum(typeName); // need check method name
    if (type == null) return null;
    return new ResourceRef(type, name);
}
```
